    <p style="font-size:16px;"><strong style="color:#fde68a;">Tunajifunza nini leo?</strong> Tutachunguza jinsi matini simulizi ilivyojengwa: msuko (ploti), mandhari na wahusika pamoja na sifa zao, kwa kutumia matini “Cherehani ya Matumaini”.</p>
