    <p>Kaunti yako ina watu wengi waliobuni ajira zao: mafundi, wakulima, wauzaji, wapishi, mafundi cherehani, wahudumu wa boda boda na wengine. Simulizi zao zina ujumbe, fani na lugha kama “Cherehani ya Matumaini”. Wewe utakuwa mtafiti mdogo wa lugha!</p>
