    <div style="background:#052e16;border:1px solid #22c55e;border-radius:8px;padding:10px 12px;margin-top:10px;"><strong style="color:#86efac;">✅ Jibu:</strong> Kasi yake ni maneno 125 kwa dakika — inafaa kwa kusoma kwa sauti.</div>
