    <div>Viziada lugha hutofautiana kitamaduni. Katika jamii nyingi za Kenya, kumtazama mzee machoni muda mrefu kunaweza kuonekana kama ukosefu wa adabu; tazama hadhira kwa ujumla na kwa upole.</div>
